package android.content;import java.util.*;public class Intent{ComponentName component;final Map<String,Object> extras=new HashMap<>();public Intent(){}public Intent(ComponentName c){component=c;}public Intent(Intent other){component=other.component;extras.putAll(other.extras);}public ComponentName getComponent(){return component;}public Intent putExtra(String k,boolean v){extras.put(k,v);return this;}public boolean getBooleanExtra(String k,boolean fallback){Object v=extras.get(k);return v instanceof Boolean?(Boolean)v:fallback;}public String getStringExtra(String k){return (String)extras.get(k);}public Intent removeExtra(String k){extras.remove(k);return this;}public android.net.Uri getData(){return null;}}
